"use strict";!function(t){t.behaviors.dxprThemeActiveTrail={attach:function(t){if(t===document){var i=window.location.pathname,a=window.location.origin;document.querySelectorAll(".menu--main a[href]").forEach(function(t){var e=t.getAttribute("href");if(e&&!e.startsWith("#")){var r=new URL(t.href,a);if(r.origin===a&&r.pathname===i){t.classList.add("is-active");for(var n=t.closest("li");n;){n.classList.add("menu-item--active-trail"),n.classList.add("active");var c=n.parentElement;if(!c)break;n=c.closest("li")}}}})}}}}(Drupal);